// R3 i18n — message-dictionary infrastructure.
//
// MESSAGES.de/en/fr are populated today, kept key-for-key in sync. Adding
// another locale means adding a MESSAGES.<locale> object (translating every
// key already used below) and a language picker calling setLocale() — no
// further code changes to the pages that use t()/applyI18n(), since they
// never hardcode text.
//
// Two ways a string reaches the dictionary:
//   - Static HTML text (headings, labels, button text, placeholders):
//     tag the element with data-i18n="key" (textContent),
//     data-i18n-placeholder="key", data-i18n-title="key", or
//     data-i18n-aria-label="key" as needed, then call applyI18n() once
//     on load (see app.js's bottom). Several attributes can be combined
//     on one element.
//   - Dynamic strings built in app.js (status messages, confirm()/alert()
//     text, template literals): call t("key") — or t("key", {name: val})
//     for the {name}-style interpolation MESSAGES entries can use —
//     instead of writing the literal string.
//
// A key missing from the active locale (or from MESSAGES.de as the
// fallback) renders as the key itself, so a missed migration/typo is
// visibly obvious in the UI rather than silently blank.

