    // Help tab (page.help.*, help.*)
    "page.help.title": "Was kann R3?",
    "page.help.hint": "Ein kurzer Überblick, was dieses Tool tut, worauf es zugreift und was es bewusst nicht tut.",
    "help.chat.title": "💬 Chat",
    "help.chat.p1": "Stelle im Chat eine Frage in normaler Sprache. R3 sucht in den hinterlegten Dokumenten/Mailboxen nach den passendsten Textstellen, gibt sie dem Sprachmodell als Grundlage mit und antwortet darauf gestützt — nicht aus allgemeinem \"Weltwissen\".",
    "help.chat.p2": "Jede Antwort zeigt anklickbare Quellenangaben (z. B. „[Q1]“). Nur Textstellen, auf die sich die Antwort tatsächlich stützt, erscheinen als Quelle — nicht alles, was bei der Suche gefunden wurde. Über die Quelle lässt sich der Originaltext einsehen.",
    "help.chat.p3": "👍/👎 unter jeder Antwort hilft, gute von schlechten Antworten zu unterscheiden — kurz Feedback geben, wenn eine Antwort daneben liegt oder besonders treffend war.",
    "help.agent.title": "🤖 Agent",
    "help.agent.p1": "Der Agent-Modus eignet sich für Aufgaben, die mehrere Schritte brauchen, statt einer einzelnen Frage: er darf die Wissensbasis mehrfach durchsuchen, einzelne Quellen im Volltext nachlesen und (falls freigeschaltet) weitere Werkzeuge nutzen, bevor er eine abschließende Antwort gibt.",
    "help.agent.p2": "Welche Werkzeuge aktiv sind (siehe Abschnitt „Verfügbare Werkzeuge“ oben), entscheidet die Administration; nicht freigeschaltete Werkzeuge werden dem Agenten gar nicht erst angeboten.",
    "help.agent.p3": "Ist eine Aufgabe mehrdeutig (z. B. \"Storniere die Bestellung\" bei mehreren offenen Bestellungen), fragt der Agent lieber nach, statt zu raten — oft als anklickbare Auswahl-Buttons unter der Rückfrage. Ein Klick beantwortet die Rückfrage direkt, genauso als hätte man sie eingetippt.",
    "help.render.title": "🧩 Formatierte Antworten",
    "help.render.p1": "Chat und Agent stellen Antworten formatiert dar: Überschriften, Listen, Hervorhebungen und Tabellen, dazu farbig hervorgehobene JSON-/XML-Blöcke und Code mit „Kopieren“-Knopf.",
    "help.render.p2": "Wo es hilft, kann das Modell auch ein Diagramm (Mermaid, z. B. ein Flussdiagramm) oder eine kleine Datenvisualisierung (d3) zeichnen. Lässt sich ein Diagramm nicht laden (z. B. offline), wird stattdessen der Quelltext angezeigt — es geht nichts verloren.",
    "help.mail.title": "✉️ Mail",
    "help.mail.p1": "Der Mail-Tab hilft beim Formulieren — entweder als Antwortentwurf auf eine eingefügte E-Mail, oder als neue E-Mail aus ein paar Stichpunkten. Der Vorschlag stützt sich ebenfalls auf die Wissensbasis (z. B. ähnliche frühere Fälle).",
    "help.mail.p2strong": "R3 versendet nie automatisch eine E-Mail.",
    "help.mail.p2": "Jeder Entwurf landet in einem editierbaren Feld — zum Kopieren, als .eml-Datei zum Öffnen in Outlook, oder (falls freigeschaltet) zum Ablegen im Entwürfe-Ordner des Postfachs. Verschicken tut immer ein Mensch.",
    "help.mail.p3": "Über „Länge“ und „Format“ lässt sich der Entwurf steuern — kürzer/ausführlicher bzw. Fließtext oder Stichpunkte. Das ändert nur Ton und Umfang, nicht die zugrunde liegenden Fakten.",
    "help.mail.p4": "„Zusätzliche Hinweise“ nimmt einen situativen Hinweis für genau diesen einen Entwurf auf — z. B. einen bevorstehenden Termin oder eine Kommunikationsvorliebe, die weder in der eingefügten Mail noch in der Wissensbasis steht. Das fließt in die Formulierung ein, wird aber nie als neue Sachinformation über den Fall behandelt.",
    "help.mail.p5": "Nach dem Erstellen lässt sich der Entwurf weiter verfeinern, ohne die Fakten neu zu recherchieren: „Stil anwenden“ formuliert den aktuellen Text in einem anderen Tonfall um (z. B. kollegial statt förmlich), „Signatur einfügen“ ergänzt Name/Abteilung des angemeldeten Kontos am Ende.",
    "help.mail.p6": "Ist ein Postfach freigeschaltet, zeigt „Mein Postfach“ eingehende E-Mails direkt aus Outlook/Exchange an — eine Auswahl füllt die Eingabe automatisch, ganz ohne Kopieren/Einfügen von Hand. Anhänge werden dabei mitgelesen, soweit unterstützt (Text/Bilder/Office-Dokumente), und fließen in den Entwurf mit ein.",
    "help.mail.p7": "Ein fertiger Entwurf lässt sich kopieren, als .eml-Datei herunterladen, an die eigene Adresse senden oder (falls freigeschaltet) direkt im Entwürfe-Ordner des Postfachs ablegen.",
    "help.sources.title": "📚 Was steht in der Wissensbasis?",
    "help.sources.p1b": "Zwei Arten stehen immer zur Verfügung, unabhängig von der Einrichtung: hochgeladene Dateien (Admin-Bereich → Import) und einzelne Webseiten/RSS-Feeds. Je nach Einrichtung kommen weitere, unten aufgeführte Quellen hinzu.",
    "help.sources.p2": "Manche Quellenarten sind nur für bestimmte Abteilungen sichtbar, oder werden zwar zur Beantwortung genutzt, aber nicht namentlich als Quelle angezeigt (etwa bei besonders sensiblen Postfächern) — das steuert die Administration zentral, nicht jede Einzelfrage.",
    "help.tools.title": "🛠️ Verfügbare Werkzeuge",
    "help.tools.p1": "Im Agent-Modus (und teilweise im normalen Chat) kann R3 zusätzlich zur Wissensbasis-Suche gezielt weitere Werkzeuge einsetzen — welche, hängt von der Einrichtung ab. Ob ein Werkzeug für eine bestimmte Frage tatsächlich zum Einsatz kommt, kann zusätzlich von Login, Abteilung oder gewähltem Preset abhängen — was hier steht, ist also \"grundsätzlich verfügbar\", nicht zwingend \"für jede Anfrage nutzbar\".",
    "help.tools.none": "In dieser Einrichtung ist aktuell kein zusätzliches Werkzeug freigeschaltet — R3 beantwortet Fragen ausschließlich anhand der Wissensbasis.",
    "help.inactive.title": "➕ Weitere mögliche Module (aktuell nicht aktiv)",
    "help.inactive.intro": "R3 unterstützt noch weitere Quellen und Werkzeuge, die in dieser Einrichtung derzeit nicht konfiguriert oder nicht freigeschaltet sind. Eine Administration kann sie bei Bedarf unter Einstellungen aktivieren.",
    "help.credits": "R3 (RubixRAG) wird von Simon Waldherr entwickelt. Bei Fragen oder Problemen: <a href=\"mailto:simon.waldherr@rubix.com\">simon.waldherr@rubix.com</a>.",
