    "prompts.skills.concatHint": "Passt mehr als ein Skill, werden alle passenden nacheinander an den System-Prompt (index.md bzw. agent.md) angehängt, relevantester zuerst — es wird nie nur einer ausgewählt. Ein Tag muss nicht exakt im Wortlaut der Frage stehen: eine einfache Pluralerkennung berücksichtigt auch naheliegende Formen (z. B. Tag \"handschuh\" passt auch auf \"Handschuhe\").",
