    "prompts.skills.guidance.li1": "Tags als Grundform (Singular) wählen — \"Handschuhe\" im Fragetext passt automatisch auch auf den Tag \"handschuh\". Trotzdem hilft es, gängige Synonyme zusätzlich als eigene Tags aufzunehmen (z. B. sowohl \"reklamation\" als auch \"beschwerde\").",
    "prompts.skills.guidance.li2": "Wenige, spezifische Tags schlagen viele, generische — ein Tag wie \"frage\" oder \"produkt\" würde bei fast jeder Anfrage feuern und den Prompt unnötig aufblähen.",
    "prompts.skills.guidance.li3": "Der Skill-Inhalt sollte knapp und faktenorientiert sein (Tabellen, Listen, konkrete Regeln) — er wird bei jeder passenden Frage komplett mitgeschickt und kostet entsprechend Kontext/Tokens.",
