    "import.dryRun.label": "🧪 Dry-Run (nur simulieren, nichts speichern)",
    "import.files.title": "Dateien importieren",
    "import.dropzone.ariaLabel": "Dateien auswählen oder hierher ziehen",
    "import.dropzone.title": "Dateien hierher ziehen oder klicken",
