    "import.actions.upload": "Hochladen",
    "import.pst.title": "PST-/OST-Postfach importieren",
    "import.pst.hint": "Outlook-.pst- oder .ost-Export. Nach dem Hochladen zeigt R3 die enthaltenen Ordner mit Nachrichtenzahl zur Auswahl, bevor tatsächlich importiert wird. Jede E-Mail wird als eigene, zitierbare Quelle gespeichert; ein erneuter Import derselben Datei ersetzt nur geänderte Nachrichten.",
    "import.pst.selectFileLabel": "PST-/OST-Datei auswählen",
    "import.actions.loadPreview": "Vorschau laden",
    "import.actions.cancel": "Abbrechen",
    "import.pst.hint2": "Für sehr große Postfächer (mehrere GB) ist ein Browser-Upload oft unzuverlässig oder langsam. Alternativ kann die Datei direkt auf dem Server abgelegt werden (z.B. per Netzlaufwerk oder scp) — dann hier den vollständigen Pfad auf dem Server angeben, ganz ohne Upload:",
    "import.pst.serverPathLabel": "Pfad zur PST-Datei auf dem Server",
    "import.pst.serverPathPlaceholder": "z.B. /opt/r3/incoming/Postfach.pst",
    "import.pst.loadPreviewServerPath": "Vorschau laden (Server-Pfad)",
    "import.pst.debugToggle": "🔍 Debug: gefilterte Boilerplate-Absätze anzeigen",
    "import.pst.filterLabel": "PST-Ordner filtern",
    "import.pst.filterPlaceholder": "Ordner filtern…",
    "import.actions.selectAll": "Alle",
    "import.actions.selectNone": "Keine",
    "import.actions.startImport": "Import starten",
    "import.sharepoint.title": "SharePoint importieren",
    "import.sharepoint.hint": "Listet Dateien in einem SharePoint-Ordner (eine Ebene) und importiert die ausgewählten. Erfordert eine konfigurierte Azure-AD-App-Registrierung unter „Einstellungen → SharePoint“. Jede „Site-URL“ dort ist genau eine SharePoint-Site — Unterordner wie „Freigegebene Dokumente“ gehören NICHT ins Site-URL-Feld, sondern in den Ordnerpfad unten; oft ist z.B. „Support/Logistik“ tatsächlich eine eigene Unter-Site und braucht eine eigene, zusätzliche Verbindung.",
    "import.sharepoint.connectionLabel": "Verbindung",
    "import.sharepoint.folderPathLabel": "Ordnerpfad in der Dokumentbibliothek",
    "import.sharepoint.folderPathPlaceholder": "z.B. Allgemein/Vertrieb (leer = Stammordner)",
    "import.sharepoint.deltaSyncButton": "Delta-Sync jetzt",
    "import.sharepoint.deltaSyncHint": "Importiert/löscht nur, was sich seit dem letzten Delta-Sync geändert hat — unabhängig vom Ordnerpfad oben, für das ganze Drive.",
    "import.sharepoint.sitePages.title": "Site Pages (.aspx-Seiten)",
    "import.sharepoint.sitePages.hint": "Die eingebauten Wiki-/News-/Landingpages einer Site (z.B. „Neue-Mailstruktur-in-der-Logistik.aspx“) liegen in einer separaten Bibliothek, die der Ordner-Import oben nicht sieht — hier werden sie eigens aufgelistet. Nur Text-Textbausteine der Seite werden gelesen; Bilder/Einbettungen/Listen-Web-Parts tragen nichts bei.",
    "import.sharepoint.sitePages.listButton": "Seiten auflisten",
    "import.sharepoint.shareLink.title": "Freigabe-Link importieren",
    "import.sharepoint.shareLinkLabel": "Freigabe-Link(s)",
    "import.actions.import": "Importieren",
    "import.outlook.title": "Outlook / Exchange Online (Microsoft Graph)",
    "import.outlook.hint": "Listet die neuesten Nachrichten in einem freigegebenen Postfach und importiert die ausgewählten. Erfordert eine Azure-AD-App-Registrierung unter „Einstellungen → Outlook/Exchange“. Für On-Prem-Exchange oder IMAP-Postfächer siehe die IMAP-Karte weiter unten.",
    "import.imap.title": "IMAP (On-Prem Exchange / generische Postfächer)",
    "import.imap.hint": "Holt alle Nachrichten, die seit dem letzten Lauf neu im Postfach eingegangen sind (kein Vorschau-/Auswahlschritt nötig — IMAP-UIDs sind bereits fortlaufend und werden nicht doppelt importiert). Erfordert Zugangsdaten unter „Einstellungen → IMAP“.",
    "import.imap.importNowButton": "Import jetzt",
    "import.teams.title": "Microsoft Teams (Kanal-Nachrichten)",
    "import.teams.hint": "Listet die neuesten Beiträge im konfigurierten Kanal und importiert die ausgewählten (nur Hauptbeiträge, keine Thread-Antworten). Erfordert eine Azure-AD-App-Registrierung unter „Einstellungen → Microsoft Teams“.",
    "import.confluence.title": "Confluence",
    "import.confluence.hint": "Listet die zuletzt geänderten Seiten im konfigurierten Space und importiert die ausgewählten. Erfordert einen API-Token unter „Einstellungen → Confluence“.",
    "import.jira.title": "Jira",
    "import.jira.hint": "Listet die zuletzt geänderten Issues im konfigurierten Projekt und importiert die ausgewählten. Erfordert einen API-Token unter „Einstellungen → Jira“ (derselbe Atlassian-Token wie für Confluence funktioniert, falls der Account beides lesen darf).",
    "import.freshservice.title": "Freshservice",
    "import.freshservice.hint": "Listet die zuletzt geänderten Tickets und importiert die ausgewählten. Erfordert einen API-Key unter „Einstellungen → Freshservice“. Kann dort zusätzlich auf automatischen periodischen Sync gestellt werden, statt nur hier per Hand zu importieren.",
    "import.web.title": "Webseite (URL-Import)",
    "import.web.hint": "Holt eine oder mehrere Webseiten per HTTP(S) und importiert den extrahierten Text. Optional rekursiv: folgt Links auf der Seite, um eine ganze Website zu erfassen. Kein Setup nötig — aber der Server ruft exakt die eingegebenen URLs (bzw. beim Crawlen: von dort aus erreichbare Seiten) ab, also nur URLs aus vertrauenswürdigen Quellen einfügen (eine URL pro Zeile).",
    "import.web.urlsAriaLabel": "URLs zum Importieren, eine pro Zeile",
    "import.web.crawlLabel": "Rekursiv crawlen (Links auf der Seite folgen)",
    "import.web.depthLabel": "Tiefe",
    "import.web.maxPagesLabel": "Max. Seiten",
    "import.web.otherHostsLabel": "Auch andere Domains als die Start-URL zulassen",
    "import.actions.dryRunTest": "Probelauf (testen)",
    "import.rss.title": "RSS / Atom-Feed importieren",
    "import.rss.hint": "Liest die Einträge eines öffentlichen RSS- oder Atom-Feeds ein. Bereits bekannte Einträge werden über ihre Feed-ID bzw. URL übersprungen.",
    "import.rss.urlAriaLabel": "RSS- oder Atom-Feed-URL",
    "import.rss.importButton": "Feed importieren",
    "import.folder.title": "Server-Ordner importieren",
    "import.folder.hint": "Rekursiver Import eines Ordnerpfads auf dem Server — auch für SMB-Freigaben, wenn diese zuvor vom Server als lokaler Pfad eingehängt wurden.",
    "import.folder.pathLabel": "Ordnerpfad auf dem Server",
    "import.folder.importButton": "Ordner importieren",
    "import.selfSource.title": "🐕 R3-Quellcode importieren",
    "import.selfSource.hint": "Lädt R3s eigenen Quellcode (Go/JS/CSS/HTML/Markdown) in die eigene Wissensbasis, damit R3 auch Fragen zu seiner eigenen Implementierung beantworten kann — mit Zitat auf die jeweilige Datei. Läuft ausschließlich im Arbeitsverzeichnis des Server-Prozesses; Einstellungsdateien mit Zugangsdaten (z. B. settings.json) und andere sensible Pfade werden dabei grundsätzlich ausgeschlossen. Rein optional — dieser Import startet nie automatisch.",
    "import.selfSource.importButton": "R3-Quellcode importieren",

