    "mail.graphPanel.title": "Mein Postfach",
    "mail.graphPanel.hint": "Zeigt E-Mails direkt aus einem Postfach (Microsoft Exchange), ohne Copy-and-Paste — Auswahl füllt die Eingabe unten automatisch. Nur sichtbar, wenn ein Admin dies für dein Konto freigeschaltet hat.",
