    "mail.saveImap": "In Postfach-Entwürfe speichern",
    "mail.saveGraph": "In mein Outlook-Postfach speichern",
    "mail.feedback.title": "War dieser Entwurf brauchbar? Hilft, die Antwortqualität einzuschätzen.",
    "mail.tooltip.mailboxSelect": "Welches Postfach durchsucht werden soll — dein eigenes, oder ein gemeinschaftliches/Team-Postfach, das ein Admin dafür freigegeben hat.",
    "mail.tooltip.mode": "„Antwort“: eine erhaltene E-Mail einfügen, R3 schlägt eine Antwort vor. „Neue E-Mail“: Empfänger, Thema und Stichpunkte beschreiben, R3 formuliert die Mail — beides gestützt auf ähnliche Fälle aus der Wissensbasis.",
    "mail.tooltip.instructions": "Situativer Hinweis für diesen einen Entwurf — z. B. ein bevorstehender Kundentermin oder eine Kommunikationsvorliebe, die weder in der eingefügten Mail noch in der Wissensbasis steht. Fließt als Anweisung in die Formulierung ein, wird aber nicht als neue Sachinformation über den Fall behandelt.",
    "mail.tooltip.length": "Wie lang soll der Entwurf werden? Steuert nur den Umfang der Formulierung — die zugrunde liegenden Fakten aus der Wissensbasis bleiben gleich.",
    "mail.tooltip.format": "Fließtext oder gegliederte Stichpunkte im Hauptteil. Anrede und Grußformel bleiben immer normaler Fließtext.",
    "mail.tooltip.draftTo": "Optionale Empfängeradresse — landet nur im heruntergeladenen .eml bzw. im gespeicherten Postfach-Entwurf, R3 selbst versendet nie etwas. Bei einer Antwort automatisch aus der Absenderadresse der eingefügten Mail vorausgefüllt, falls erkennbar — vor dem Weiterverwenden prüfen.",
    "mail.tooltip.draftSubject": "Vorschlag von R3 („AW: …“ bei Antworten, generiert bei neuen Mails) — vor dem Weiterverwenden prüfen/anpassen.",
    "mail.tooltip.attachButton": "Datei (z. B. Scan/Foto) an diesen Entwurf anhängen — landet im gespeicherten Postfach-Entwurf, im heruntergeladenen .eml und in einer per „An mich senden“ verschickten Mail.",
    "mail.tooltip.style": "Formuliert den aktuellen Entwurfstext oben in einem anderen Stil um — Inhalt/Fakten bleiben unverändert, es ändert sich nur Tonfall und Formulierung. Wirkt auf den Text, wie er gerade im Feld oben steht, inklusive eigener Änderungen.",
    "mail.tooltip.restyle": "Formt den Entwurfstext oben in den links gewählten Stil um, ohne den fachlichen Inhalt zu verändern.",
    "mail.tooltip.regenerate": "Verwirft diesen Entwurf und lässt aus derselben Eingabe einen neuen generieren — z. B. wenn der Ton oder die Formulierung nicht passt. Bereits vorgenommene Änderungen an Betreff/Text gehen dabei verloren.",
    "mail.tooltip.insertSignature": "Fügt am Ende des Entwurfstexts eine Signatur mit Name/Abteilung des angemeldeten Kontos ein (ohne Anmeldung: Platzhalter zum Ausfüllen von Hand) — ersetzt dabei eine bereits vorhandene Grußformel/Signatur, damit keine doppelte entsteht. R3 selbst schlägt nie einen fremden Namen als Absender vor.",
    "mail.tooltip.downloadEml": "Lädt den Entwurf als .eml-Datei herunter — lässt sich in Outlook & Co. öffnen und von dort als normale Mail weiterbearbeiten/versenden.",
    "mail.tooltip.sendSelf": "Schickt den Entwurf als E-Mail an die eigene, im Konto hinterlegte Adresse — zur Weiterbearbeitung im eigenen Mail-Programm. Nur dorthin, nie an eine andere Adresse; erfordert eine Anmeldung und konfiguriertes SMTP.",
    "mail.tooltip.saveImap": "Legt den Entwurf per IMAP im Entwürfe-Ordner des konfigurierten Postfachs ab (Einstellungen → IMAP → Entwürfe-Ordner). Nur ablegen — geprüft und versendet wird weiterhin von einem Menschen im Mail-Programm.",
    "mail.tooltip.saveGraph": "Legt diesen Entwurf direkt im Entwürfe-Ordner deines eigenen Outlook-Postfachs ab (Microsoft Graph), als Antwort auf die oben ausgewählte Nachricht. Nur ablegen — geprüft und versendet wird weiterhin von dir selbst in Outlook.",

