    "prompts.draftPrompt.hint": 'System prompt for reply drafts — used by the "Create reply draft" button in the source view AND by the public "Mail" tab. Without a custom file, a built-in default prompt applies.',
    "prompts.draftPrompt.ariaLabel": "Draft-reply prompt content",
    "prompts.draftPrompt.saveButton": "Save draft-reply prompt",
    "prompts.agentPrompt.title": "Agent prompt (agent.md)",
    "prompts.agentPrompt.hint": "System prompt for Chat's Agent tier — task-oriented rather than plain knowledge-base Q&A, may use available tools. Without a custom file, a built-in default prompt applies.",
    "prompts.agentPrompt.ariaLabel": "Agent prompt content",
    "prompts.agentPrompt.saveButton": "Save agent prompt",
    "prompts.skills.title": "Skills",
    "prompts.skills.hint": "A skill is only inserted into the prompt when one of its tags appears in the question. Disabled skills are never used.",
    "prompts.skills.concatHint": "When more than one skill matches, every matching one is appended to the system prompt (index.md or agent.md) in turn, most relevant first — it's never just one. A tag doesn't have to appear verbatim in the question: a simple plural fallback also catches close forms (e.g. tag \"glove\" also matches \"gloves\").",
    "prompts.skills.guidance.summary": "💡 Tips for writing good skills",
    "prompts.skills.guidance.li1": "Write tags as a base/singular form — a question containing \"gloves\" automatically also matches the tag \"glove\". It still helps to add common synonyms as their own tags too (e.g. both \"complaint\" and \"claim\").",
    "prompts.skills.guidance.li2": "Few, specific tags beat many generic ones — a tag like \"question\" or \"product\" would fire on almost every request and needlessly bloat the prompt.",
    "prompts.skills.guidance.li3": "Skill content should be concise and fact-oriented (tables, lists, concrete rules) — it's sent in full on every matching question, at a corresponding context/token cost.",
    "prompts.skills.guidance.li4": "Use the test question below before saving to check the chosen tags actually fire as expected.",
