    "import.sharepoint.title": "Import from SharePoint",
    "import.sharepoint.hint": 'Lists files in a SharePoint folder (one level) and imports the selected ones. Requires a configured Azure AD app registration under "Settings → SharePoint". Each "Site URL" there is exactly one SharePoint site — subfolders like "Shared Documents" do NOT belong in the Site URL field, but in the folder path below; often e.g. "Support/Logistics" is actually its own sub-site and needs its own, additional connection.',
    "import.sharepoint.connectionLabel": "Connection",
    "import.sharepoint.folderPathLabel": "Folder path in the document library",
