    "import.sharepoint.deltaSyncHint": "Imports/deletes only what changed since the last delta sync — regardless of the folder path above, for the whole drive.",
    "import.sharepoint.sitePages.title": "Site pages (.aspx pages)",
    "import.sharepoint.sitePages.hint": 'A site\'s built-in wiki/news/landing pages (e.g. "New-mail-structure-in-logistics.aspx") live in a separate library the folder import above can\'t see — they\'re listed separately here. Only the page\'s text content blocks are read; images/embeds/list web parts contribute nothing.',
    "import.sharepoint.sitePages.listButton": "List pages",
    "import.sharepoint.shareLink.title": "Import a share link",
    "import.sharepoint.shareLinkLabel": "Share link(s)",
