    "import.outlook.title": "Outlook / Exchange Online (Microsoft Graph)",
    "import.outlook.hint": 'Lists the newest messages in a shared mailbox and imports the selected ones. Requires an Azure AD app registration under "Settings → Outlook/Exchange". For on-prem Exchange or IMAP mailboxes see the IMAP card further below.',
    "import.imap.title": "IMAP (on-prem Exchange / generic mailboxes)",
    "import.imap.hint": 'Fetches every message that has newly arrived in the mailbox since the last run (no preview/selection step needed — IMAP UIDs are already sequential and never imported twice). Requires credentials under "Settings → IMAP".',
    "import.imap.importNowButton": "Import now",
    "import.teams.title": "Microsoft Teams (channel messages)",
    "import.teams.hint": 'Lists the newest posts in the configured channel and imports the selected ones (top-level posts only, no thread replies). Requires an Azure AD app registration under "Settings → Microsoft Teams".',
    "import.confluence.title": "Confluence",
    "import.confluence.hint": 'Lists the most recently changed pages in the configured space and imports the selected ones. Requires an API token under "Settings → Confluence".',
    "import.jira.title": "Jira",
    "import.jira.hint": 'Lists the most recently changed issues in the configured project and imports the selected ones. Requires an API token under "Settings → Jira" (the same Atlassian token used for Confluence works if the account can read both).',
    "import.freshservice.title": "Freshservice",
    "import.freshservice.hint": 'Lists the most recently changed tickets and imports the selected ones. Requires an API key under "Settings → Freshservice". Can additionally be set there to sync automatically on a schedule instead of only importing here by hand.',
    "import.web.title": "Web page (URL import)",
    "import.web.hint": "Fetches one or more web pages over HTTP(S) and imports the extracted text. Optionally recursive: follows links on the page to capture a whole website. No setup needed — but the server fetches exactly the entered URLs (or, when crawling: pages reachable from them), so only paste URLs from trusted sources (one URL per line).",
    "import.web.urlsAriaLabel": "URLs to import, one per line",
