    "import.selfSource.hint": "Loads R3's own source code (Go/JS/CSS/HTML/Markdown) into its own knowledge base, so R3 can also answer questions about its own implementation — with a citation pointing at the actual file. Only ever runs inside the server process's own working directory; settings files holding credentials (e.g. settings.json) and other sensitive paths are always excluded. Purely optional — this import never starts automatically.",
    "import.selfSource.importButton": "Import R3's source code",

