    "mail.feedback.title": "Was this draft useful? Helps gauge answer quality.",
    "mail.tooltip.mailboxSelect": "Which mailbox to search — your own, or a shared/team mailbox an admin has enabled for you.",
    "mail.tooltip.mode": "\"Reply\": paste a received email, R3 proposes a reply. \"New email\": describe recipient, topic and key points, R3 drafts the email — both grounded in similar cases from the knowledge base.",
    "mail.tooltip.instructions": "A situational note for this one draft — e.g. an upcoming customer appointment or a communication preference that's in neither the pasted email nor the knowledge base. Feeds into the wording as an instruction, but is never treated as a new fact about the case.",
    "mail.tooltip.length": "How long should the draft be? Only controls the scope of the wording — the underlying facts from the knowledge base stay the same.",
    "mail.tooltip.format": "Prose or structured bullet points in the main body. Salutation and closing always stay plain prose.",
    "mail.tooltip.draftTo": "Optional recipient address — only used in the downloaded .eml or the saved mailbox draft, R3 itself never sends anything. For a reply, auto-filled from the pasted email's sender address when recognizable — check before reusing it.",
    "mail.tooltip.draftSubject": "R3's suggestion (\"RE: ...\" for replies, generated for new emails) — check/adjust before reusing it.",
    "mail.tooltip.attachButton": "Attach a file (e.g. a scan/photo) to this draft — included in the saved mailbox draft, the downloaded .eml, and an email sent via \"Send to myself\".",
    "mail.tooltip.style": "Rewrites the current draft text above in a different style — content/facts stay unchanged, only tone and wording change. Acts on the text exactly as it currently stands in the field above, including your own edits.",
    "mail.tooltip.restyle": "Reshapes the draft text above into the style selected on the left, without changing the factual content.",
    "mail.tooltip.regenerate": "Discards this draft and generates a new one from the same input — e.g. when the tone or wording doesn't fit. Any changes already made to subject/body are lost.",
    "mail.tooltip.insertSignature": "Inserts a signature with the logged-in account's name/department at the end of the draft text (without login: a placeholder to fill in by hand) — replaces any existing closing/signature so it doesn't end up duplicated. R3 itself never proposes someone else's name as the sender.",
    "mail.tooltip.downloadEml": "Downloads the draft as an .eml file — can be opened in Outlook & co. and edited/sent from there as a normal email.",
    "mail.tooltip.sendSelf": "Sends the draft as an email to your own address on file with your account — for further editing in your own mail program. Only ever to that address, never anywhere else; requires being logged in and SMTP to be configured.",
    "mail.tooltip.saveImap": "Files the draft via IMAP into the configured mailbox's drafts folder (Settings → IMAP → Drafts folder). Only files it — a human still reviews and sends it from their mail program.",
    "mail.tooltip.saveGraph": "Files this draft directly into your own Outlook mailbox's drafts folder (Microsoft Graph), as a reply to the message selected above. Only files it — you still review and send it yourself in Outlook.",

