    "prompts.departmentRules.hintHtml": 'Maps the AD attributes <code>department</code>/<code>title</code> to department codes at login (see Settings -> "Access control per source type"). A JSON array of objects <code>{"regex": "...", "code": "..."}</code>, evaluated in order — the first matching rule wins. Without a custom file, built-in default rules apply (see <code>department.go</code>). Changes take effect at that person\'s next login, not retroactively for already-signed-in sessions.',
