    "prompts.systemPrompt.saveButton": "Enregistrer le prompt système",
    "prompts.draftPrompt.title": "Prompt de brouillon de réponse (draft.md)",
    "prompts.draftPrompt.hint": "Prompt système pour les brouillons de réponse — utilisé par le bouton « Créer un brouillon de réponse » dans la vue des sources ET par l'onglet public « Mail ». Sans fichier personnalisé, un prompt par défaut intégré s'applique.",
    "prompts.draftPrompt.ariaLabel": "Contenu du prompt de brouillon de réponse",
    "prompts.draftPrompt.saveButton": "Enregistrer le prompt de brouillon de réponse",
    "prompts.agentPrompt.title": "Prompt de l'agent (agent.md)",
    "prompts.agentPrompt.hint": "Prompt système pour la palier Agent du Chat — orienté tâche plutôt que simple question-réponse sur la base de connaissances, peut utiliser les outils disponibles. Sans fichier personnalisé, un prompt par défaut intégré s'applique.",
    "prompts.agentPrompt.ariaLabel": "Contenu du prompt de l'agent",
    "prompts.agentPrompt.saveButton": "Enregistrer le prompt de l'agent",
    "prompts.skills.title": "Skills",
    "prompts.skills.hint": "Un skill n'est inséré dans le prompt que si l'un de ses tags apparaît dans la question. Les skills désactivés ne sont jamais utilisés.",
    "prompts.skills.concatHint": "Si plusieurs skills correspondent, tous sont ajoutés au prompt système (index.md ou agent.md) à la suite, le plus pertinent en premier — ce n'est jamais un seul. Un tag n'a pas besoin d'apparaître mot pour mot dans la question : une détection simple du pluriel reconnaît aussi les formes proches (p. ex. le tag « gant » correspond aussi à « gants »).",
    "prompts.skills.guidance.summary": "💡 Conseils pour rédiger de bons skills",
    "prompts.skills.guidance.li1": "Choisir des tags à la forme de base (singulier) — « gants » dans la question correspond automatiquement aussi au tag « gant ». Il reste utile d'ajouter aussi les synonymes courants comme tags séparés (p. ex. à la fois « réclamation » et « plainte »).",
    "prompts.skills.guidance.li2": "Peu de tags spécifiques valent mieux que beaucoup de tags génériques — un tag comme « question » ou « produit » se déclencherait sur presque toutes les requêtes et alourdirait inutilement le prompt.",
    "prompts.skills.guidance.li3": "Le contenu d'un skill doit être concis et factuel (tableaux, listes, règles concrètes) — il est envoyé en entier à chaque question correspondante, avec le coût de contexte/tokens que cela implique.",
    "prompts.skills.guidance.li4": "Utiliser la question de test ci-dessous avant d'enregistrer pour vérifier que les tags choisis se déclenchent bien comme prévu.",
    "prompts.skills.tester.label": "Question de test",
    "prompts.skills.tester.placeholder": "Saisissez une question de test pour voir quels skills enregistrés se déclencheraient…",
    "prompts.skills.tester.title": "Vérifie, à partir d'une question d'exemple, lesquels des skills enregistrés et activés ci-dessus seraient réellement sélectionnés — n'appelle aucune IA, évalue uniquement la correspondance des tags (la même logique qu'à l'exécution).",
    "prompts.skills.tester.button": "Tester",
    "prompts.skills.tester.testing": "Vérification…",
    "prompts.skills.tester.noneMatched": "Aucun skill enregistré ne se déclencherait pour cette question.",
    "prompts.skills.tester.matched": "Se déclencherait : {skills}",
    "prompts.skills.tester.emptyQuestion": "Veuillez d'abord saisir une question de test.",
    "prompts.skills.addButton": "+ Créer un nouveau skill",
