    "prompts.departmentRules.ariaLabel": "JSON des règles de service",
    "prompts.departmentRules.saveButton": "Enregistrer",
    "prompts.departmentRules.resetButton": "Réinitialiser par défaut",

    // Import tab (tab-import.html) — headings/hints/buttons
    "import.dryRun.label": "🧪 Essai à blanc (simulation uniquement, rien n'est enregistré)",
    "import.files.title": "Importer des fichiers",
    "import.dropzone.ariaLabel": "Sélectionner des fichiers ou les déposer ici",
    "import.dropzone.title": "Glissez des fichiers ici ou cliquez",
    "import.dropzone.emptyState": "Aucun fichier sélectionné",
    "import.files.selectLabel": "Sélectionner des fichiers",
    "import.files.keepOriginal": "Conserver le fichier original (permet un téléchargement ultérieur via la citation)",
    "import.actions.upload": "Téléverser",
    "import.pst.title": "Importer une boîte mail PST/OST",
    "import.pst.hint": "Export .pst ou .ost d'Outlook. Après le téléversement, R3 affiche les dossiers contenus avec leur nombre de messages à sélectionner avant l'import effectif. Chaque e-mail est enregistré comme sa propre source citable ; un nouvel import du même fichier ne remplace que les messages modifiés.",
    "import.pst.selectFileLabel": "Sélectionner le fichier PST/OST",
    "import.actions.loadPreview": "Charger l'aperçu",
    "import.actions.cancel": "Annuler",
    "import.pst.hint2": "Pour les très grandes boîtes mail (plusieurs Go), un téléversement navigateur est souvent peu fiable ou lent. Le fichier peut aussi être déposé directement sur le serveur (p. ex. via un lecteur réseau ou scp) — indiquez alors ici le chemin complet sur le serveur, sans aucun téléversement :",
    "import.pst.serverPathLabel": "Chemin du fichier PST sur le serveur",
    "import.pst.serverPathPlaceholder": "p. ex. /opt/r3/incoming/boitemail.pst",
    "import.pst.loadPreviewServerPath": "Charger l'aperçu (chemin serveur)",
    "import.pst.debugToggle": "🔍 Débogage : afficher les paragraphes de texte standard filtrés",
    "import.pst.filterLabel": "Filtrer les dossiers PST",
    "import.pst.filterPlaceholder": "Filtrer les dossiers…",
    "import.actions.selectAll": "Tous",
    "import.actions.selectNone": "Aucun",
    "import.actions.startImport": "Démarrer l'import",
    "import.sharepoint.title": "Importer depuis SharePoint",
    "import.sharepoint.hint": "Liste les fichiers d'un dossier SharePoint (un niveau) et importe ceux sélectionnés. Nécessite une inscription d'application Azure AD configurée sous « Paramètres → SharePoint ». Chaque « URL de site » y est exactement un site SharePoint — les sous-dossiers comme « Documents partagés » ne vont PAS dans le champ URL de site, mais dans le chemin de dossier ci-dessous ; souvent, p. ex. « Support/Logistique » est en fait un sous-site propre et nécessite sa propre connexion supplémentaire.",
    "import.sharepoint.connectionLabel": "Connexion",
    "import.sharepoint.folderPathLabel": "Chemin de dossier dans la bibliothèque de documents",
    "import.sharepoint.folderPathPlaceholder": "p. ex. Général/Ventes (vide = dossier racine)",
    "import.sharepoint.deltaSyncButton": "Synchronisation delta maintenant",
    "import.sharepoint.deltaSyncHint": "N'importe/ne supprime que ce qui a changé depuis la dernière synchronisation delta — indépendamment du chemin de dossier ci-dessus, pour tout le lecteur.",
    "import.sharepoint.sitePages.title": "Pages de site (pages .aspx)",
    "import.sharepoint.sitePages.hint": "Les pages wiki/actualités/d'accueil intégrées d'un site (p. ex. « Nouvelle-structure-mail-logistique.aspx ») se trouvent dans une bibliothèque séparée que l'import de dossier ci-dessus ne voit pas — elles sont listées ici séparément. Seuls les blocs de texte de la page sont lus ; images/intégrations/web parts de liste n'apportent rien.",
    "import.sharepoint.sitePages.listButton": "Lister les pages",
    "import.sharepoint.shareLink.title": "Importer un lien de partage",
    "import.sharepoint.shareLinkLabel": "Lien(s) de partage",
    "import.actions.import": "Importer",
    "import.outlook.title": "Outlook / Exchange Online (Microsoft Graph)",
    "import.outlook.hint": "Liste les messages les plus récents d'une boîte mail partagée et importe ceux sélectionnés. Nécessite une inscription d'application Azure AD sous « Paramètres → Outlook/Exchange ». Pour Exchange On-Prem ou les boîtes IMAP, voir la carte IMAP plus bas.",
    "import.imap.title": "IMAP (Exchange On-Prem / boîtes mail génériques)",
    "import.imap.hint": "Récupère tous les messages arrivés dans la boîte mail depuis la dernière exécution (aucune étape d'aperçu/sélection nécessaire — les UID IMAP sont déjà séquentiels et ne sont jamais importés deux fois). Nécessite des identifiants sous « Paramètres → IMAP ».",
    "import.imap.importNowButton": "Importer maintenant",
    "import.teams.title": "Microsoft Teams (messages de canal)",
    "import.teams.hint": "Liste les publications les plus récentes du canal configuré et importe celles sélectionnées (messages principaux uniquement, pas les réponses de fil). Nécessite une inscription d'application Azure AD sous « Paramètres → Microsoft Teams ».",
    "import.confluence.title": "Confluence",
    "import.confluence.hint": "Liste les pages les plus récemment modifiées de l'espace configuré et importe celles sélectionnées. Nécessite un jeton API sous « Paramètres → Confluence ».",
    "import.jira.title": "Jira",
    "import.jira.hint": "Liste les tickets les plus récemment modifiés du projet configuré et importe ceux sélectionnés. Nécessite un jeton API sous « Paramètres → Jira » (le même jeton Atlassian que pour Confluence fonctionne si le compte peut lire les deux).",
    "import.freshservice.title": "Freshservice",
    "import.freshservice.hint": "Liste les tickets les plus récemment modifiés et importe ceux sélectionnés. Nécessite une clé API sous « Paramètres → Freshservice ». Peut y être configuré en plus pour une synchronisation périodique automatique, au lieu d'importer uniquement ici à la main.",
    "import.web.title": "Page web (import par URL)",
    "import.web.hint": "Récupère une ou plusieurs pages web via HTTP(S) et importe le texte extrait. Optionnellement récursif : suit les liens de la page pour capturer un site entier. Aucune configuration nécessaire — mais le serveur récupère exactement les URL saisies (ou, en cas de crawl : les pages accessibles depuis celles-ci), donc ne collez que des URL de sources fiables (une URL par ligne).",
    "import.web.urlsAriaLabel": "URL à importer, une par ligne",
    "import.web.crawlLabel": "Crawler récursivement (suivre les liens de la page)",
    "import.web.depthLabel": "Profondeur",
    "import.web.maxPagesLabel": "Pages max.",
    "import.web.otherHostsLabel": "Autoriser aussi d'autres domaines que l'URL de départ",
    "import.actions.dryRunTest": "Essai à blanc (tester)",
    "import.rss.title": "Importer un flux RSS/Atom",
    "import.rss.hint": "Lit les entrées d'un flux RSS ou Atom public. Les entrées déjà connues sont ignorées via leur ID de flux ou leur URL.",
    "import.rss.urlAriaLabel": "URL du flux RSS ou Atom",
    "import.rss.importButton": "Importer le flux",
    "import.folder.title": "Importer un dossier serveur",
    "import.folder.hint": "Import récursif d'un chemin de dossier sur le serveur — fonctionne aussi pour les partages SMB, une fois montés par le serveur comme chemin local.",
    "import.folder.pathLabel": "Chemin de dossier sur le serveur",
    "import.folder.importButton": "Importer le dossier",
    "import.selfSource.title": "🐕 Importer le code source de R3",
    "import.selfSource.hint": "Charge le propre code source de R3 (Go/JS/CSS/HTML/Markdown) dans sa propre base de connaissances, afin que R3 puisse aussi répondre à des questions sur sa propre implémentation — avec une citation pointant vers le fichier concerné. Ne s'exécute que dans le répertoire de travail du processus serveur ; les fichiers de configuration contenant des identifiants (par ex. settings.json) et autres chemins sensibles sont toujours exclus. Purement optionnel — cet import ne démarre jamais automatiquement.",
    "import.selfSource.importButton": "Importer le code source de R3",

