    "mail.feedback.title": "Ce brouillon était-il utile ? Aide à évaluer la qualité des réponses.",
    "mail.tooltip.mailboxSelect": "La boîte mail à consulter — la vôtre, ou une boîte mail partagée/d'équipe qu'un administrateur a activée pour vous.",
    "mail.tooltip.mode": "« Réponse » : collez un e-mail reçu, R3 propose une réponse. « Nouvel e-mail » : décrivez destinataire, sujet et points clés, R3 rédige l'e-mail — les deux s'appuient sur des cas similaires de la base de connaissances.",
    "mail.tooltip.instructions": "Une remarque situationnelle pour ce seul brouillon — p. ex. un rendez-vous client à venir ou une préférence de communication qui ne figure ni dans l'e-mail collé ni dans la base de connaissances. Influence la formulation comme une instruction, mais n'est jamais traitée comme un nouveau fait sur le dossier.",
    "mail.tooltip.length": "Quelle doit être la longueur du brouillon ? Ne contrôle que l'ampleur de la formulation — les faits sous-jacents de la base de connaissances restent inchangés.",
    "mail.tooltip.format": "Texte suivi ou puces structurées dans le corps principal. La formule d'appel et la formule de politesse restent toujours en texte suivi.",
    "mail.tooltip.draftTo": "Adresse du destinataire facultative — utilisée uniquement dans le .eml téléchargé ou le brouillon enregistré dans la boîte mail, R3 lui-même n'envoie jamais rien. Pour une réponse, préremplie automatiquement à partir de l'adresse de l'expéditeur de l'e-mail collé si elle est reconnaissable — à vérifier avant réutilisation.",
    "mail.tooltip.draftSubject": "Suggestion de R3 (« RE : … » pour les réponses, générée pour les nouveaux e-mails) — à vérifier/ajuster avant réutilisation.",
    "mail.tooltip.attachButton": "Joindre un fichier (p. ex. un scan/une photo) à ce brouillon — inclus dans le brouillon enregistré dans la boîte mail, le .eml téléchargé et un e-mail envoyé via « Me l'envoyer ».",
    "mail.tooltip.style": "Reformule le texte du brouillon ci-dessus dans un autre style — le contenu/les faits restent inchangés, seuls le ton et la formulation changent. Agit sur le texte tel qu'il apparaît actuellement dans le champ ci-dessus, y compris vos propres modifications.",
    "mail.tooltip.restyle": "Reformule le texte du brouillon ci-dessus dans le style sélectionné à gauche, sans modifier le contenu factuel.",
    "mail.tooltip.regenerate": "Rejette ce brouillon et en génère un nouveau à partir de la même saisie — p. ex. si le ton ou la formulation ne convient pas. Les modifications déjà apportées à l'objet/au texte sont perdues.",
    "mail.tooltip.insertSignature": "Insère une signature avec le nom/département du compte connecté à la fin du texte du brouillon (sans connexion : un espace réservé à remplir à la main) — remplace une formule de politesse/signature déjà présente pour éviter les doublons. R3 lui-même ne propose jamais le nom d'une autre personne comme expéditeur.",
    "mail.tooltip.downloadEml": "Télécharge le brouillon sous forme de fichier .eml — peut être ouvert dans Outlook & co. et modifié/envoyé de là comme un e-mail normal.",
    "mail.tooltip.sendSelf": "Envoie le brouillon par e-mail à votre propre adresse enregistrée dans votre compte — pour une modification ultérieure dans votre propre logiciel de messagerie. Uniquement vers cette adresse, jamais vers une autre ; nécessite une connexion et SMTP configuré.",
    "mail.tooltip.saveImap": "Dépose le brouillon via IMAP dans le dossier brouillons de la boîte mail configurée (Paramètres → IMAP → Dossier brouillons). Le dépose uniquement — un humain le vérifie et l'envoie toujours depuis son logiciel de messagerie.",
    "mail.tooltip.saveGraph": "Dépose ce brouillon directement dans le dossier brouillons de votre propre boîte Outlook (Microsoft Graph), en tant que réponse au message sélectionné ci-dessus. Le dépose uniquement — vous le vérifiez et l'envoyez toujours vous-même dans Outlook.",

