    "nav.help": "Aiuto",

    // Help tab (page.help.*, help.*)
    "page.help.title": "Cosa può fare R3?",
    "page.help.hint": "Una rapida panoramica di cosa fa questo strumento, a cosa accede e cosa deliberatamente non fa.",
    "help.chat.title": "💬 Chat",
    "help.chat.p1": "Fai una domanda nella Chat in linguaggio naturale. R3 cerca nei documenti/caselle di posta memorizzati i passaggi più pertinenti, li fornisce al modello linguistico come base, e risponde basandosi su di essi — non sulla \"conoscenza generale\".",
    "help.chat.p2": "Ogni risposta mostra citazioni cliccabili (ad es. „[Q1]“). Solo i passaggi su cui la risposta si basa realmente compaiono come fonte — non tutto ciò che la ricerca ha trovato. La citazione apre il testo originale.",
    "help.chat.p3": "👍/👎 sotto ogni risposta aiuta a distinguere le risposte buone da quelle cattive — un rapido feedback ogni volta che una risposta non coglie nel segno o è particolarmente azzeccata.",
    "help.agent.title": "🤖 Agent",
    "help.agent.p1": "La modalità Agent è adatta a compiti che richiedono più passaggi anziché una singola domanda: può cercare più volte nella base di conoscenza, leggere singole fonti per intero e (se abilitato) usare ulteriori strumenti prima di dare una risposta finale.",
    "help.agent.p2": "Quali strumenti sono attivi (vedi la sezione \"Strumenti disponibili\" sopra) è deciso dall'amministrazione; gli strumenti non abilitati non vengono mai offerti all'agente.",
    "help.agent.p3": "Se un compito è ambiguo (ad es. \"annulla l'ordine\" con più ordini aperti), l'agente preferisce chiedere piuttosto che indovinare — spesso sotto forma di pulsanti opzione cliccabili sotto la domanda di chiarimento. Cliccandone uno si risponde direttamente alla domanda, esattamente come se fosse stata digitata.",
    "help.render.title": "🧩 Risposte formattate",
    "help.render.p1": "Chat e Agent visualizzano le risposte con formattazione: titoli, elenchi, evidenziazioni e tabelle, oltre a blocchi JSON/XML colorati e codice con un pulsante per copiare.",
    "help.render.p2": "Quando è utile, il modello può anche disegnare un diagramma (Mermaid, ad es. un diagramma di flusso) o una piccola visualizzazione dati (d3). Se un diagramma non può essere caricato (ad es. offline), viene mostrato il suo codice sorgente al suo posto — non si perde nulla.",
    "help.mail.title": "✉️ Mail",
    "help.mail.p1": "La scheda Mail aiuta nella formulazione — sia come bozza di risposta a un'email incollata, sia come nuova email a partire da alcuni punti chiave. Il suggerimento si basa anch'esso sulla base di conoscenza (ad es. casi simili passati).",
    "help.mail.p2strong": "R3 non invia mai un'email automaticamente.",
    "help.mail.p2": "Ogni bozza finisce in un campo modificabile — da copiare, come file .eml da aprire in Outlook, oppure (se abilitato) da archiviare nella cartella bozze della casella di posta. L'invio effettivo è sempre eseguito da una persona.",
    "help.mail.p3": "\"Lunghezza\" e \"Formato\" permettono di orientare la bozza — più breve/più lunga, testo continuo o punti elenco. Questo cambia solo tono e lunghezza, mai i fatti sottostanti.",
    "help.mail.p4": "\"Note aggiuntive\" raccoglie una nota situazionale per questa singola bozza — ad es. un appuntamento imminente o una preferenza di comunicazione non presente né nell'email incollata né nella knowledge base. Influenza la formulazione, ma non viene mai trattata come un nuovo fatto sul caso.",
    "help.mail.p5": "Dopo la generazione, la bozza può essere ulteriormente affinata senza ricercare di nuovo i fatti: \"Applica stile\" riformula il testo attuale in un tono diverso (ad es. colloquiale invece che formale), \"Inserisci firma\" aggiunge nome/reparto dell'account collegato alla fine.",
    "help.mail.p6": "Se una casella è abilitata, \"La mia casella\" mostra le email in arrivo direttamente da Outlook/Exchange — una selezione riempie automaticamente il campo, senza copia-incolla manuale. Gli allegati vengono letti dove supportato (testo/immagini/documenti Office) e confluiscono nella bozza.",
    "help.mail.p7": "Una bozza completata può essere copiata, scaricata come file .eml, inviata al proprio indirizzo oppure (se abilitato) depositata direttamente nella cartella bozze della casella.",
    "help.sources.title": "📚 Cosa contiene la base di conoscenza?",
    "help.sources.p1b": "Due tipi sono sempre disponibili, indipendentemente dalla configurazione: file caricati (area Admin → Import) e singole pagine web/feed RSS. A seconda della configurazione, si aggiungono le fonti elencate di seguito.",
    "help.sources.p2": "Alcuni tipi di fonte sono visibili solo a determinati reparti, oppure vengono usati per rispondere senza essere mostrati per nome come fonte (ad es. per caselle di posta particolarmente sensibili) — questo è controllato centralmente dall'amministrazione, non caso per caso.",
    "help.tools.title": "🛠️ Strumenti disponibili",
    "help.tools.p1": "In modalità Agent (e in parte nella Chat normale), R3 può usare ulteriori strumenti oltre alla ricerca nella base di conoscenza — quali, dipende dalla configurazione. Se uno strumento viene effettivamente usato per una determinata domanda può inoltre dipendere dal login, dal reparto o dal preset scelto — quanto elencato qui è quindi \"disponibile in linea di principio\", non necessariamente \"utilizzabile per ogni richiesta\".",
    "help.tools.none": "In questa installazione non è attualmente abilitato alcuno strumento aggiuntivo — R3 risponde alle domande esclusivamente in base alla base di conoscenza.",
    "help.inactive.title": "➕ Altri moduli possibili (non attivi al momento)",
    "help.inactive.intro": "R3 supporta ulteriori fonti e strumenti che al momento non sono configurati o abilitati in questa installazione. Un amministratore può abilitarli se necessario nelle Impostazioni.",
    "help.credits": "R3 (RubixRAG) è sviluppato da Simon Waldherr. Per domande o problemi: <a href=\"mailto:simon.waldherr@rubix.com\">simon.waldherr@rubix.com</a>.",
