    "help.privacy.title": "🔒 Cosa R3 non fa",
    "help.privacy.li1": "Nessuna email inviata automaticamente — ogni bozza richiede una persona che la invii.",
    "help.privacy.li2": "Nessuna risposta \"dal nulla\" senza una fonte nella chat normale — la base di una risposta può sempre essere verificata tramite le sue citazioni.",
    "help.privacy.li3": "Nessun accesso a contenuti non collegati, e nessuna elusione delle restrizioni di reparto/accesso che si applicano al proprio account.",
    "help.tips.title": "⚙️ Alcuni consigli",
    "help.tips.li1": "Domande specifiche (con nomi, periodi, numeri di ticket, ecc.) ottengono risposte più precise rispetto a domande molto generiche.",
    "help.tips.li2": "Tema e dimensione del carattere possono essere regolati in fondo alla barra laterale — la scelta resta salvata nel browser.",
    "help.tips.li3": "\"Cronologia\" ricorda le conversazioni passate solo in questo browser (non sul server) — comodo per domande di approfondimento successive sullo stesso argomento.",
