    "chunks.filter.embedModelTitle": "Nome esatto del modello (non una sottostringa!) — ad es. \"text-embedding-3-small\" o il nome del modello locale. Il nome esatto è indicato nella vista dettagliata espansa di ogni chunk (Modello di embedding) o in Impostazioni → Archiviazione.",
    "chunks.table.freshnessTitle": "Decadimento esponenziale a partire dalla data propria del documento (in mancanza di una data del documento, si usa il tempo di caricamento) — 100% = appena caricato, poi in costante diminuzione. Il tasso di decadimento (dimezzamento) è configurabile in Impostazioni → Retrieval/Ranking → \"Dimezzamento aggiornamento\". Influisce solo sull'ordinamento della ricerca (recency_weight), mai sul fatto che un documento venga trovato o meno.",
    "chunks.searchTest.title": "Ricerca di prova",
    "chunks.searchTest.hint": "Esegue per una domanda di esempio la stessa ricerca usata da Chat/Agent (punteggio vettoriale + parole chiave + aggiornamento, vedi Impostazioni → Retrieval/Ranking) — senza chiamata al modello linguistico, solo la ricerca pura. Aiuta a capire perché una determinata fonte compare (o non compare) per una domanda, o se la ponderazione è impostata in modo sensato. Viene eseguita senza restrizioni (come un amministratore), indipendentemente dalle restrizioni di reparto/preset.",
