    // Jobs page
    "jobs.reload": "Aggiorna",
    "jobs.active.title": "Job attivi",
    "jobs.active.hint": "Una riga per ogni connessione abilitata di tutti i connettori di import (Impostazioni → SharePoint/Exchange/IMAP/Teams/Confluence/Jira/Freshservice/Cartella server) — anche senza un intervallo configurato (in tal caso avviabile solo manualmente). \"Esegui ora\" avvia immediatamente la sincronizzazione completa di questa connessione, indipendentemente da intervallo e pausa; \"Annulla\" interrompe un job in esecuzione (agisce tra un elemento e l'altro, non a metà di una richiesta); \"Pausa\" sospende solo il ritmo automatico, senza dimenticare l'intervallo configurato — gli import manuali restano possibili. Si aggiorna automaticamente finché questa scheda resta aperta.",
