    "prompts.usingBuiltinDefault": "ℹ️ Non è ancora stato salvato alcun file personalizzato — il testo mostrato sotto è il prompt predefinito integrato. Salvare lo riprende invariato come punto di partenza per personalizzarlo.",
    "prompts.systemPrompt.ariaLabel": "Contenuto del prompt di sistema",
