    "prompts.draftPrompt.title": "Prompt bozza di risposta (draft.md)",
    "prompts.draftPrompt.hint": 'Prompt di sistema per le bozze di risposta — usato dal pulsante "Crea bozza di risposta" nella vista fonte E dalla scheda pubblica "Mail". Senza un file personalizzato si applica un prompt predefinito integrato.',
    "prompts.draftPrompt.ariaLabel": "Contenuto del prompt bozza di risposta",
    "prompts.draftPrompt.saveButton": "Salva prompt bozza di risposta",
    "prompts.agentPrompt.title": "Prompt Agent (agent.md)",
    "prompts.agentPrompt.hint": "Prompt di sistema per la stufa Agent nel Chat — orientato al compito anziché a semplici Q&A sulla base di conoscenza, può usare gli strumenti disponibili. Senza un file personalizzato si applica un prompt predefinito integrato.",
    "prompts.agentPrompt.ariaLabel": "Contenuto del prompt Agent",
    "prompts.agentPrompt.saveButton": "Salva prompt Agent",
    "prompts.skills.title": "Skill",
    "prompts.skills.hint": "Una skill viene inserita nel prompt solo se uno dei suoi tag compare nella domanda. Le skill disattivate non vengono mai usate.",
    "prompts.skills.concatHint": "Se corrisponde più di una skill, tutte quelle corrispondenti vengono aggiunte in sequenza al prompt di sistema (index.md o agent.md), la più rilevante per prima — non viene mai scelta solo una. Un tag non deve comparire esattamente nel testo della domanda: un semplice riconoscimento del plurale considera anche forme simili (ad es. il tag \"guanto\" corrisponde anche a \"guanti\").",
    "prompts.skills.guidance.summary": "💡 Consigli per scrivere buone skill",
    "prompts.skills.guidance.li1": "Scegliere i tag nella forma base (singolare) — \"guanti\" nel testo della domanda corrisponde automaticamente anche al tag \"guanto\". È comunque utile aggiungere anche i sinonimi comuni come tag propri (ad es. sia \"reclamo\" che \"lamentela\").",
    "prompts.skills.guidance.li2": "Pochi tag specifici sono meglio di molti tag generici — un tag come \"domanda\" o \"prodotto\" scatterebbe per quasi ogni richiesta, gonfiando inutilmente il prompt.",
    "prompts.skills.guidance.li3": "Il contenuto della skill dovrebbe essere conciso e orientato ai fatti (tabelle, elenchi, regole concrete) — viene inviato per intero a ogni domanda corrispondente, con il relativo costo in contesto/token.",
    "prompts.skills.guidance.li4": "Usare la domanda di prova qui sotto prima di salvare per verificare che i tag scelti scattino davvero come previsto.",
    "prompts.skills.tester.label": "Domanda di prova",
    "prompts.skills.tester.placeholder": "Inserisci una domanda di prova per vedere quali skill salvate scatterebbero…",
