    "import.pst.hint": "Export .pst o .ost di Outlook. Dopo il caricamento, R3 mostra le cartelle contenute con il numero di messaggi da selezionare prima dell'import effettivo. Ogni email viene salvata come fonte citabile a sé stante; un nuovo import dello stesso file sostituisce solo i messaggi modificati.",
