    "import.sharepoint.title": "Importa da SharePoint",
    "import.sharepoint.hint": 'Elenca i file in una cartella SharePoint (un livello) e importa quelli selezionati. Richiede una registrazione app Azure AD configurata sotto "Impostazioni → SharePoint". Ogni "URL sito" lì è esattamente un sito SharePoint — le sottocartelle come "Documenti condivisi" NON vanno nel campo URL sito, ma nel percorso cartella sotto; spesso, ad es. "Support/Logistica" è in realtà un sotto-sito proprio e richiede una propria connessione aggiuntiva.',
    "import.sharepoint.connectionLabel": "Connessione",
    "import.sharepoint.folderPathLabel": "Percorso cartella nella raccolta documenti",
    "import.sharepoint.folderPathPlaceholder": "ad es. Generale/Vendite (vuoto = cartella radice)",
    "import.sharepoint.deltaSyncButton": "Sincronizzazione delta ora",
    "import.sharepoint.deltaSyncHint": "Importa/elimina solo ciò che è cambiato dall'ultima sincronizzazione delta — indipendentemente dal percorso cartella sopra, per l'intero drive.",
    "import.sharepoint.sitePages.title": "Site Pages (pagine .aspx)",
    "import.sharepoint.sitePages.hint": 'Le pagine wiki/notizie/landing integrate di un sito (ad es. "Nuova-struttura-mail-logistica.aspx") si trovano in una raccolta separata che l\'import cartelle sopra non vede — qui vengono elencate separatamente. Vengono lette solo le porzioni di testo della pagina; immagini/incorporamenti/web part elenco non contribuiscono.',
    "import.sharepoint.sitePages.listButton": "Elenca pagine",
