    "import.sharepoint.shareLinkLabel": "Link di condivisione",
    "import.actions.import": "Importa",
    "import.outlook.title": "Outlook / Exchange Online (Microsoft Graph)",
    "import.outlook.hint": 'Elenca i messaggi più recenti in una casella condivisa e importa quelli selezionati. Richiede una registrazione app Azure AD sotto "Impostazioni → Outlook/Exchange". Per Exchange On-Prem o caselle IMAP vedi la scheda IMAP più sotto.',
    "import.imap.title": "IMAP (Exchange On-Prem / caselle generiche)",
    "import.imap.hint": 'Recupera tutti i messaggi arrivati nella casella dall\'ultima esecuzione (nessun passaggio di anteprima/selezione necessario — gli UID IMAP sono già progressivi e non vengono mai importati due volte). Richiede credenziali sotto "Impostazioni → IMAP".',
    "import.imap.importNowButton": "Importa ora",
    "import.teams.title": "Microsoft Teams (messaggi di canale)",
    "import.teams.hint": 'Elenca i post più recenti nel canale configurato e importa quelli selezionati (solo post principali, non le risposte nei thread). Richiede una registrazione app Azure AD sotto "Impostazioni → Microsoft Teams".',
    "import.confluence.title": "Confluence",
    "import.confluence.hint": 'Elenca le pagine modificate più di recente nello space configurato e importa quelle selezionate. Richiede un token API sotto "Impostazioni → Confluence".',
    "import.jira.title": "Jira",
    "import.jira.hint": 'Elenca gli issue modificati più di recente nel progetto configurato e importa quelli selezionati. Richiede un token API sotto "Impostazioni → Jira" (lo stesso token Atlassian usato per Confluence funziona se l\'account può leggere entrambi).',
    "import.freshservice.title": "Freshservice",
    "import.freshservice.hint": 'Elenca i ticket modificati più di recente e importa quelli selezionati. Richiede una API key sotto "Impostazioni → Freshservice". Può essere impostato lì anche per una sincronizzazione periodica automatica, invece di importare solo qui manualmente.',
    "import.web.title": "Pagina web (import da URL)",
    "import.web.hint": "Recupera una o più pagine web via HTTP(S) e importa il testo estratto. Opzionalmente ricorsivo: segue i link nella pagina per catturare un intero sito web. Nessuna configurazione necessaria — ma il server recupera esattamente gli URL inseriti (o, durante il crawling: le pagine raggiungibili da essi), quindi incolla solo URL da fonti attendibili (un URL per riga).",
