    "mail.sendSelf": "Invia a me",
    "mail.saveImap": "Salva nelle bozze della casella",
    "mail.saveGraph": "Salva nella mia casella Outlook",
    "mail.feedback.title": "Questa bozza era utile? Aiuta a valutare la qualità delle risposte.",
    "mail.tooltip.mailboxSelect": "Quale casella cercare — la propria, oppure una casella condivisa/di team che un amministratore ha abilitato per te.",
    "mail.tooltip.mode": "\"Risposta\": incolla un'email ricevuta, R3 propone una risposta. \"Nuova email\": descrivi destinatario, argomento e punti chiave, R3 redige l'email — entrambi basati su casi simili della knowledge base.",
    "mail.tooltip.instructions": "Una nota situazionale per questa singola bozza — ad es. un appuntamento imminente con il cliente o una preferenza di comunicazione non presente né nell'email incollata né nella knowledge base. Influenza la formulazione come istruzione, ma non viene mai trattata come un nuovo fatto sul caso.",
    "mail.tooltip.length": "Quanto deve essere lunga la bozza? Controlla solo l'estensione della formulazione — i fatti sottostanti dalla knowledge base restano invariati.",
    "mail.tooltip.format": "Testo continuo o punti elenco strutturati nel corpo principale. Formula di apertura e chiusura restano sempre testo continuo.",
    "mail.tooltip.draftTo": "Indirizzo destinatario opzionale — utilizzato solo nel file .eml scaricato o nella bozza salvata nella casella, R3 stesso non invia mai nulla. Per una risposta, precompilato automaticamente dall'indirizzo del mittente dell'email incollata se riconoscibile — da verificare prima di riutilizzarlo.",
    "mail.tooltip.draftSubject": "Suggerimento di R3 (\"RE: ...\" per le risposte, generato per le nuove email) — da verificare/adattare prima di riutilizzarlo.",
    "mail.tooltip.attachButton": "Allega un file (ad es. una scansione/foto) a questa bozza — incluso nella bozza salvata nella casella, nel file .eml scaricato e in un'email inviata tramite \"Invia a me\".",
    "mail.tooltip.style": "Riformula il testo della bozza qui sopra in uno stile diverso — contenuto/fatti restano invariati, cambiano solo tono e formulazione. Agisce sul testo esattamente come si presenta ora nel campo sopra, incluse le modifiche apportate.",
    "mail.tooltip.restyle": "Trasforma il testo della bozza sopra nello stile selezionato a sinistra, senza modificare il contenuto fattuale.",
    "mail.tooltip.regenerate": "Scarta questa bozza e ne genera una nuova dallo stesso input — ad es. se il tono o la formulazione non sono adatti. Le modifiche già apportate a oggetto/testo andranno perse.",
    "mail.tooltip.insertSignature": "Inserisce una firma con nome/reparto dell'account collegato alla fine del testo della bozza (senza accesso: un segnaposto da compilare a mano) — sostituisce un eventuale saluto/firma già presente per evitare duplicati. R3 stesso non propone mai il nome di un'altra persona come mittente.",
    "mail.tooltip.downloadEml": "Scarica la bozza come file .eml — apribile in Outlook e simili e modificabile/inviabile da lì come una normale email.",
    "mail.tooltip.sendSelf": "Invia la bozza come email al proprio indirizzo registrato nell'account — per la modifica successiva nel proprio programma di posta. Solo a quell'indirizzo, mai a un altro; richiede l'accesso e SMTP configurato.",
    "mail.tooltip.saveImap": "Deposita la bozza via IMAP nella cartella bozze della casella configurata (Impostazioni → IMAP → Cartella bozze). La deposita soltanto — una persona la verifica e la invia comunque dal proprio programma di posta.",
    "mail.tooltip.saveGraph": "Deposita questa bozza direttamente nella cartella bozze della propria casella Outlook (Microsoft Graph), come risposta al messaggio selezionato sopra. La deposita soltanto — la verifichi e la invii comunque tu stesso in Outlook.",

