let currentLocale = "de";

// setLocale switches the active locale (falling back to "de" if unknown),
// updates <html lang>, and re-applies all data-i18n* markup.
function setLocale(locale) {
  currentLocale = MESSAGES[locale] ? locale : "de";
  document.documentElement.setAttribute("lang", currentLocale);
  applyI18n();
}

// t looks up key in the active locale (falling back to de, then to key
// itself) and interpolates any {name} placeholders from vars.
function t(key, vars) {
  const dict = MESSAGES[currentLocale] || MESSAGES.de;
  let s = (dict && dict[key]) ?? (MESSAGES.de && MESSAGES.de[key]) ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      s = s.replaceAll(`{${k}}`, v);
    }
  }
  return s;
}

// applyI18n hydrates every data-i18n* element under root — call it once
// on initial load, and again after setLocale() or after injecting new
// markup (e.g. a template-literal-built table row) that itself carries
// data-i18n attributes.
function applyI18n(root) {
  root = root || document;
  root.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll("[data-i18n-placeholder]").forEach(el => { el.placeholder = t(el.dataset.i18nPlaceholder); });
  root.querySelectorAll("[data-i18n-title]").forEach(el => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll("[data-i18n-aria-label]").forEach(el => { el.setAttribute("aria-label", t(el.dataset.i18nAriaLabel)); });
  // data-i18n-html is data-i18n's innerHTML counterpart, for the rare hint
  // that embeds static markup (e.g. <code> around a field/file name) —
  // plain data-i18n would escape that markup as literal text. The
  // translated value itself carries the HTML, authored by us (never user
  // input), same trust level as any other template literal already
  // assigned via innerHTML elsewhere in this codebase.
  root.querySelectorAll("[data-i18n-html]").forEach(el => { el.innerHTML = t(el.dataset.i18nHtml); });
}
